vec2 hash(vec2 p) {
    p = vec2(dot(p, vec2(8910520913.0, 23320985871.0)), dot(p, vec2(1212758091.0, 809328791.0)));
    return fract(sin(p) *5093.432885) * 2.0 - 1.0;
}

vec2 rotate(vec2 p, float angle) {
    float c = cos(angle);
    float s = sin(angle);
    return vec2(c * p.x - s * p.y, s * p.x + c * p.y);
}

float noise(vec2 uv) {
    vec2 p0 = floor(uv);
    vec2 p1 = p0 + vec2(1.0, 0.0);
    vec2 p2 = p0 + vec2(0.0, 1.0);
    vec2 p3 = p0 + vec2(1.0, 1.0);

    // Gradient vectors
    vec2 g0 = hash(p0);
    vec2 g1 = hash(p1);
    vec2 g2 = hash(p2);
    vec2 g3 = hash(p3);

    // Distance vectors
    vec2 d0 = uv - p0;
    vec2 d1 = uv - p1;
    vec2 d2 = uv - p2;
    vec2 d3 = uv - p3;

    // Dot products
    float v0 = dot(g0, d0);
    float v1 = dot(g1, d1);
    float v2 = dot(g2, d2);
    float v3 = dot(g3, d3);

    // Interpolation
    vec2 f = fract(uv);
    vec2 u = f * f * (3.0 - 2.0 * f);

    float x0 = mix(v0, v1, u.x);
    float x1 = mix(v2, v3, u.x);

    return mix(x0, x1, u.y)*0.5+0.5;
}

float noise2(vec2 uv)
{
    float x0 = floor(uv.x);
    float y0 = floor(uv.y);
    float x1 = x0 + 1.0;
    float y1 = y0 + 1.0;

    // Different Animations
    //float t = iTime*2.0;
    //float t = sin(0.1*iTime)*30.0*sin(0.1*iTime);
    //float t = 10.0*sin(iTime*0.2)+1.0;
    //float t = 4.0*sin(length(uv)*2.0 + iTime);
    //float t = 1.5*sin(uv.x*-2.0 + iTime*1.5);
    float t = 2.0*iTime;
    //float t = 0.0;

    //gradient vectors
    vec2 gv00 = rotate(hash(vec2(x0,y0)),t);
    vec2 gv01 = rotate(hash(vec2(x0,y1)),t);
    vec2 gv10 = rotate(hash(vec2(x1,y0)),t);
    vec2 gv11 = rotate(hash(vec2(x1,y1)),t);

    //distance vectors
    vec2 dist00 = uv - vec2(x0,y0);
    vec2 dist01 = uv - vec2(x0,y1);
    vec2 dist10 = uv - vec2(x1,y0);
    vec2 dist11 = uv - vec2(x1,y1);

    //dot product of gradient and dist vectors
    float d00 = dot(gv00,dist00);
    float d01 = dot(gv01,dist01);
    float d10 = dot(gv10,dist10);
    float d11 = dot(gv11,dist11);

    //interpolation
    vec2 f = fract(uv);
    vec2 u = f*f*(3.0 - 2.0*f);
    //vec2 u = 0.5 * (tanh(6.0*f - 3.0) + 1.0); 

    float x2 = mix(d00, d01, u.y);
    float x3 = mix(d10, d11, u.y);

    float col = mix(x2, x3, u.x) * 0.5 + 0.4;
    return col;
}

float dist(vec2 uv, float angle, float len, vec2 p) {
    // Move to the grid point and rotate
    uv -= p;
    uv = rotate(uv, angle);

    // Constrain distance to the line segment
    return length(uv - vec2(clamp(uv.x-0.006, -0.07 / 2.0, 0.07 / 2.0), 0.0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;
    uv *= 3.0;
    uv.y -= 0.5;

    vec3 col = vec3(1.0);

    // Define the size of the pixel box
    float boxSize = 0.08;

    // Find the center of the box where we draw the line segment
    vec2 nearestPoint = floor(uv / boxSize) * boxSize + vec2(0.5 * boxSize);

    // Compute the angle based on Perlin noise at the center of the 20x20 pixel box
    float x = sin(iTime*0.7);
    float angle = noise(nearestPoint) * 1.0 * 3.1415 - (3.1415/2.0);
    angle = 3.1415 * (6.0*cos(noise2(nearestPoint)) - 1.0);

    float idk = 0.01;
    //if(angle <= 0.1) angle=0.0;
    //else angle=(3.1415/4.0);


    // Compute distance to the line segment (within the box)
    float t = dist(uv, angle, boxSize-(boxSize/4.0), nearestPoint);

    col -= smoothstep(idk, 0.0, t);
    col *= vec3(0.8,0.4,0.0);

    col += 0.2*noise2(uv);

    fragColor = vec4(col, 1.0);
}
